package com.lexorion.payroll.service;
import com.lexorion.payroll.api.PayRunDtos.PayRunResponse;import com.lexorion.payroll.entitlement.PayrollProcessingEntitlementGate;import org.springframework.stereotype.Service;
@Service public class PayRunProcessingService{private final PayrollWorkspaceScope scope;private final PayrollProcessingEntitlementGate entitlement;private final PayRunTransactions transactions;private final PayRunService runs;public PayRunProcessingService(PayrollWorkspaceScope s,PayrollProcessingEntitlementGate e,PayRunTransactions t,PayRunService r){scope=s;entitlement=e;transactions=t;runs=r;}public PayRunResponse process(String key){entitlement.requireProcessing(scope.context());transactions.begin(key);try{transactions.complete(key);return runs.get(key);}catch(RuntimeException failure){transactions.fail(key);throw failure;}}}
